import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.DnrXFDHb.js";const m=JSON.parse('{"title":"学习地图","description":"AI 综合知识库学习地图，按 AI 基础、大模型原理、应用实践、AI 绘画与资源五类主题查找内容，并提供按目标选读和一周入门建议。","frontmatter":{"description":"AI 综合知识库学习地图，按 AI 基础、大模型原理、应用实践、AI 绘画与资源五类主题查找内容，并提供按目标选读和一周入门建议。"},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788697768000}'),o={name:"guide/getting-started.md"};function i(n,a,s,h,d,g){return t(),r("div",null,[...a[0]||(a[0]=[l(`<h1 id="学习地图" tabindex="-1">学习地图 <a class="header-anchor" href="#学习地图" aria-label="Permalink to &quot;学习地图&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 本站是一份按主题查阅的手册；AI 基础提供共同概念，大模型原理、应用实践和 AI 绘画可以按目标选择，资源与术语表则适合在阅读过程中随时查阅。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>本页是全站地图，可以直接从这里开始，不要求先读任何其他页面。</li><li>不要求编程经验，也不要求数学基础；各页涉及的新术语都会先解释。</li><li>本页只帮助你找到入口和组合页面，具体概念以对应正文为准。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>说出本站各主题分别回答什么问题。</li><li>根据当前目标选出最相关的几页，而不是被迫读完整站。</li><li>为零基础入门安排一周的可选练习，并留下可检查的产出。</li><li>遇到陌生概念时，知道该用搜索、术语表还是主题侧栏定位。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="知识库由哪些主题组成" tabindex="-1">知识库由哪些主题组成 <a class="header-anchor" href="#知识库由哪些主题组成" aria-label="Permalink to &quot;知识库由哪些主题组成&quot;">​</a></h3><p>本站的主题关系可以概括为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─ 大模型原理 ──┐</span></span>
<span class="line"><span>共同基础（AI 基础） ├─ 应用实践      ├─ 按目标组合阅读</span></span>
<span class="line"><span>                    └─ AI 绘画 ─────┘</span></span>
<span class="line"><span>资源与术语表：阅读任何主题时都可以随时查阅</span></span></code></pre></div><ul><li><strong>AI 基础。</strong> <a href="/ai/basics">AI 基础概念</a>、<a href="/ai/machine-learning">机器学习入门</a>、<a href="/ai/neural-networks">神经网络直觉</a>，用于理解模型、训练、参数、泛化和神经网络等共通知识。</li><li><strong>大模型原理。</strong> <a href="/llm/basics">大模型入门</a>、<a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>、<a href="/llm/transformer">Transformer 直觉</a>、<a href="/llm/inference-decoding">推理与解码</a>、<a href="/llm/training-alignment">训练、微调与对齐</a>，用于理解文本怎样进入模型、回答怎样生成以及能力怎样形成。</li><li><strong>应用实践。</strong> <a href="/prompting/basics">Prompt 入门</a>、<a href="/prompting/evaluation">效果评估</a>、<a href="/llm/rag-agent">RAG 与 Agent</a>、<a href="/workflows/workflow-vs-template">工作流和模板区别</a>、<a href="/tools/common-tools">常用工具</a>，用于把模型能力组织成明确、可验证、可复用的任务流程。</li><li><strong>AI 绘画。</strong> <a href="/concepts/base-model">底模是什么</a>、<a href="/concepts/components">AI 绘画由哪些部分组成</a>、<a href="/concepts/how-it-works">基本原理</a>、<a href="/models/ecosystems">常见模型生态</a>、<a href="/lora/basics">LoRA 入门</a>，用于理解图像生成系统及常见模型文件。</li><li><strong>资源。</strong> <a href="/resources/websites">常用网站</a>、<a href="/resources/tutorials">精选教程</a>、<a href="/glossary">术语表</a>，用于查来源、找教程和确认词义，不需要单独“学完”。</li></ul><h3 id="如何选择入口" tabindex="-1">如何选择入口 <a class="header-anchor" href="#如何选择入口" aria-label="Permalink to &quot;如何选择入口&quot;">​</a></h3><ul><li>完全不确定从哪里开始：先读 <a href="/ai/basics">AI 基础概念</a>，再用 <a href="/llm/basics">大模型入门</a>了解当前主流生成式 AI 的整体图景。</li><li>已经有明确目标：直接从下面的“按目标选读”进入，对不熟悉的前置概念再回头补充。</li><li>只记得一个术语：优先用顶部搜索；仍不确定含义和关联时，再查<a href="/glossary">术语表</a>。</li><li>正在使用某个产品：先在<a href="/tools/common-tools">常用工具</a>判断它属于哪类，再去对应原理或实践页面。</li></ul><h3 id="起步卡住了怎么办" tabindex="-1">起步卡住了怎么办 <a class="header-anchor" href="#起步卡住了怎么办" aria-label="Permalink to &quot;起步卡住了怎么办&quot;">​</a></h3><p>选好入口之后，阅读中常见的卡点可以用“症状 → 处理”来对照：</p><ul><li><strong>术语看不懂</strong>：先查<a href="/glossary">术语表</a>的对应词条，每个词条都标注了详细讲解所在的正文页面；词条读完仍不清楚，再按指引去正文。</li><li><strong>某一页读不下去</strong>：多半是前置没补齐。回到该页开头的“前置知识”，先读它列出的页面，回来通常就顺了。</li><li><strong>推演部分看不懂每一步</strong>：推演是自愿细读的部分，先跳过、只读概念和结论，不影响后续页面；需要时再回来重算一遍。</li><li><strong>路线太长读不完</strong>：路线是完整版，不是必答题。对照“重点记住”一列，只保留与当前目标直接相关的前几页，其余等真正用到再补。</li><li><strong>读完记不住</strong>：这很正常。各页的“自测问题”就是为此准备的——做不出来再回读对应小节，比反复通读省时间。</li></ul><h3 id="每个主题读到什么程度就够用" tabindex="-1">每个主题读到什么程度就够用 <a class="header-anchor" href="#每个主题读到什么程度就够用" aria-label="Permalink to &quot;每个主题读到什么程度就够用&quot;">​</a></h3><ul><li>AI 基础：能区分 AI、机器学习、深度学习和模型，并解释过拟合与泛化。</li><li>大模型原理：能说清文本如何变成 Token、模型如何利用上下文、生成时采样参数改变了什么。</li><li>应用实践：能写出包含角色、任务、上下文、输出格式、约束和示例六要素的 Prompt，判断何时需要 RAG、工作流或 Agent，并用固定测试集验证改动效果。</li><li>AI 绘画：能说出底模、VAE、采样器和 LoRA 的分工，并看懂最小文生图流程。</li><li>资源：知道怎样核对官方文档、版本和许可证，并保存可追溯的学习记录。</li></ul><h3 id="怎么判断自己已经入门" tabindex="-1">怎么判断自己已经入门 <a class="header-anchor" href="#怎么判断自己已经入门" aria-label="Permalink to &quot;怎么判断自己已经入门&quot;">​</a></h3><p>“入门”不等于“读完”。可以按路线用下面这些信号自检，它们大多对应各页末尾的自测问题：</p><ul><li><strong>快速用上对话 AI</strong>：能不查资料地向朋友解释幻觉和知识截止为什么发生，并写出一个带约束和输出格式的 Prompt 稳定完成任务。</li><li><strong>搞懂大模型原理</strong>：能独立做出各原理页的自测题，例如说清“预测下一个 Token 为什么能产生对话能力”，以及采样参数改变了什么、没改变什么。</li><li><strong>搭建 RAG 或 Agent</strong>：遇到一个失败的案例，能判断该怪检索、怪 Prompt 还是怪模型，并知道分别怎么排查。</li><li><strong>画 AI 插画</strong>：拿到一张不满意的图，能按底模、提示词、采样参数、LoRA 的顺序给出排查方向。</li><li><strong>组织可复用任务</strong>：能把一个模糊需求拆成带固定步骤和测试集的流程，并说明每一步为什么可靠。</li></ul><p>信号做不出来不代表白学——它准确指出了该回哪一页、补哪一小节。</p><h2 id="按目标选读" tabindex="-1">按目标选读 <a class="header-anchor" href="#按目标选读" aria-label="Permalink to &quot;按目标选读&quot;">​</a></h2><p>下面每一行都是独立入口；箭头只表示这条目标路线中的建议先后，不代表全站阅读顺序。</p><table tabindex="0"><thead><tr><th>目标</th><th>建议组合</th><th>重点记住</th></tr></thead><tbody><tr><td>快速用上对话 AI</td><td><a href="/ai/basics">AI 基础概念</a> → <a href="/llm/basics">大模型入门</a> → <a href="/prompting/basics">Prompt 入门</a> → <a href="/tools/common-tools">常用工具</a></td><td>Token、上下文窗口、幻觉、结果验证</td></tr><tr><td>搞懂大模型原理</td><td><a href="/ai/basics">AI 基础概念</a> → <a href="/ai/machine-learning">机器学习入门</a> → <a href="/ai/neural-networks">神经网络直觉</a> → <a href="/llm/basics">大模型入门</a> → <a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a> → <a href="/llm/transformer">Transformer 直觉</a> → <a href="/llm/inference-decoding">推理与解码</a> → <a href="/llm/training-alignment">训练、微调与对齐</a></td><td>注意力、自回归生成、训练与推理</td></tr><tr><td>搭建 RAG 或 Agent</td><td><a href="/llm/basics">大模型入门</a> → <a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a> → <a href="/prompting/basics">Prompt 入门</a> → <a href="/llm/training-alignment">训练、微调与对齐</a> → <a href="/llm/rag-agent">RAG 与 Agent</a> → <a href="/workflows/workflow-vs-template">工作流和模板区别</a></td><td>检索质量、工具权限、失败路径</td></tr><tr><td>画 AI 插画</td><td><a href="/ai/basics">AI 基础概念</a> → <a href="/concepts/base-model">底模是什么</a> → <a href="/concepts/components">AI 绘画由哪些部分组成</a> → <a href="/concepts/how-it-works">基本原理</a> → <a href="/models/ecosystems">常见模型生态</a> → <a href="/lora/basics">LoRA 入门</a> → <a href="/concepts/controlnet">ControlNet 入门</a></td><td>底模、采样、生态兼容性、LoRA、可控构图</td></tr><tr><td>组织可复用任务</td><td><a href="/prompting/basics">Prompt 入门</a> → <a href="/workflows/workflow-vs-template">工作流和模板区别</a> → <a href="/llm/rag-agent">RAG 与 Agent</a> → <a href="/tools/common-tools">常用工具</a> → <a href="/prompting/evaluation">效果评估</a></td><td>输入输出、固定步骤、动态决策、审计、测试集与基线</td></tr></tbody></table><p>路线只是入口。读到不熟悉的概念时回到相关页面补充；已经掌握的内容可以跳过，不需要为了“完成进度”重复阅读。</p><h3 id="每条路线为什么这样排" tabindex="-1">每条路线为什么这样排 <a class="header-anchor" href="#每条路线为什么这样排" aria-label="Permalink to &quot;每条路线为什么这样排&quot;">​</a></h3><p>同一张表换一个视角看：每条路线的先后都有一条可以点破的逻辑。知道它，跳读时才知道自己跳过了什么。</p><ul><li><strong>快速用上对话 AI</strong>：先读两页基础，是为了拿到 Token、上下文窗口、幻觉这几个词——没有它们，<a href="/prompting/basics">Prompt 入门</a>里的“约束”“示例”只能照抄而不懂为什么；直接跳到 Prompt 也能用，但输出不稳定时会缺少排查的语言。工具页放最后，因为工具只是调用模型，先知道模型能做什么，选工具才不浪费时间。</li><li><strong>搞懂大模型原理</strong>：这条路线基本是一条依赖链——<a href="/ai/basics">AI 基础概念</a>给词汇，<a href="/ai/machine-learning">机器学习入门</a>给“训练”这个概念，<a href="/ai/neural-networks">神经网络直觉</a>讲参数怎么被调整，<a href="/llm/basics">大模型入门</a>把三者串成 LLM 图景，之后四页再逐层拆开。最容易卡的地方是从 Transformer 直接开始：注意力的推演要用到 Token 向量和损失的概念，缺了会觉得每句话都在引入新名词。</li><li><strong>搭建 RAG 或 Agent</strong>：从<a href="/llm/basics">大模型入门</a>直接起步，跳过了 AI 基础两页，默认你已带齐基础词汇，不熟就先补 <a href="/ai/basics">AI 基础概念</a>。顺序的逻辑：<a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>决定检索质量的一半（文本怎么被切开和表示），<a href="/prompting/basics">Prompt 入门</a>决定另一半（拿到资料后怎么问）；<a href="/llm/training-alignment">训练、微调与对齐</a>帮你判断什么时候该微调而不是继续堆检索；<a href="/llm/rag-agent">RAG 与 Agent</a>才谈架构，工作流页收尾工程化。跳过 Prompt 直接上框架，容易做出“检索都对、回答不行”的系统，还说不清问题出在哪一层。</li><li><strong>画 AI 插画</strong>：先认识底模这个核心对象，再看部件分工，然后才是原理与生态——因为“换底模”“VAE”“采样器”这些日常操作词，都建立在知道系统由什么组成之上。<a href="/ai/basics">AI 基础概念</a>放最前，是让“模型是训练产物”这句话先立住；ControlNet 排最后，因为可控构图要用到前面认识的所有部件。</li><li><strong>组织可复用任务</strong>：这个顺序和真实搭建顺序一致——<a href="/prompting/basics">Prompt 入门</a>是最小单元，工作流把多个 Prompt 串成流程，RAG 与 Agent 往流程里加检索和动态决策，工具页提供承载方式，评估页最后把关。倒过来先装框架再想 Prompt，常在“每一步都不稳定”上耗尽耐心。</li></ul><h2 id="动手试试-可选的一周入门" tabindex="-1">动手试试：可选的一周入门 <a class="header-anchor" href="#动手试试-可选的一周入门" aria-label="Permalink to &quot;动手试试：可选的一周入门&quot;">​</a></h2><p>如果你还没有明确目标，可以用下面这条一周路线建立最小共同基础。它不是全站必修顺序，时间紧张时也可以整体拉长：</p><ul><li><strong>第 1-2 天</strong>：读 <a href="/ai/basics">AI 基础概念</a> 和 <a href="/ai/machine-learning">机器学习入门</a>，用自己的话写 5 句话说明 AI、机器学习、深度学习、模型、训练和推理的关系。</li><li><strong>第 3-4 天</strong>：读 <a href="/llm/basics">大模型入门</a>，用常见对话助手做三个小实验：解释熟悉概念、总结长文、回答较新的事实问题，并核对结果。</li><li><strong>第 5 天</strong>：读 <a href="/prompting/basics">Prompt 入门</a>，把角色、任务、上下文、输出格式、约束和示例用在一个真实小任务上。</li><li><strong>第 6 天</strong>：选择一个方向：读 <a href="/llm/rag-agent">RAG 与 Agent</a>、<a href="/concepts/base-model">底模是什么</a>或<a href="/workflows/workflow-vs-template">工作流和模板区别</a>。</li><li><strong>第 7 天</strong>：使用搜索和<a href="/glossary">术语表</a>整理本周仍不清楚的词，并决定接下来深入哪个主题。</li></ul><p>一周结束时应留下：一页概念笔记、三份实验记录、一条改进过的 Prompt，以及一份“仍需查清”的术语清单。判断是否有收获，看这些产出能否说明你的理解，而不是看读了多少页。</p><h2 id="不同背景读者怎么选" tabindex="-1">不同背景读者怎么选 <a class="header-anchor" href="#不同背景读者怎么选" aria-label="Permalink to &quot;不同背景读者怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>读者背景</th><th>建议入口</th><th>暂时不必深入</th><th>当前目标</th></tr></thead><tbody><tr><td>完全零基础</td><td><a href="/guide/getting-started">学习地图</a> → <a href="/ai/basics">AI 基础概念</a> → <a href="/llm/basics">大模型入门</a>，然后选择一个主题</td><td>神经网络和 Transformer 的推演细节</td><td>建立概念图并找到主方向</td></tr><tr><td>有编程经验</td><td><a href="/llm/basics">大模型入门</a>、<a href="/llm/inference-decoding">推理与解码</a>、<a href="/llm/training-alignment">训练、微调与对齐</a>、<a href="/llm/rag-agent">RAG 与 Agent</a></td><td>已熟悉的机器学习直觉内容</td><td>理解模型的工程行为与成本</td></tr><tr><td>主要使用 AI 绘画</td><td><a href="/concepts/base-model">底模是什么</a>、<a href="/concepts/components">AI 绘画由哪些部分组成</a>、<a href="/concepts/how-it-works">基本原理</a>、<a href="/models/ecosystems">常见模型生态</a>、<a href="/lora/basics">LoRA 入门</a>、<a href="/concepts/controlnet">ControlNet 入门</a></td><td>大模型原理的大部分页面</td><td>看懂工作流并定位出图问题</td></tr><tr><td>主要使用对话模型</td><td><a href="/llm/basics">大模型入门</a>、<a href="/prompting/basics">Prompt 入门</a>、<a href="/llm/rag-agent">RAG 与 Agent</a>、<a href="/prompting/evaluation">效果评估</a>、<a href="/tools/common-tools">常用工具</a></td><td>AI 绘画专题</td><td>稳定地交付任务并验证结果</td></tr></tbody></table><p>这些入口不是身份标签。需求变化时直接切换主题即可；不需要先把原来的方向全部读完。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“必须从首页一路读到最后一页”</strong>：不同目标需要的知识组合不同；只要补齐当前页面标出的前置概念，就可以直接进入相关主题。</li><li><strong>“背会提示词模板就能用好 AI”</strong>：Prompt 是任务说明而不是咒语；不理解模型、数据和工具之间的关系，换个任务就容易失效。</li><li><strong>“演示或训练时的表现就是真实效果”</strong>：真实效果要结合验证数据、测试数据和自己的任务来看。</li><li><strong>“调高 Temperature、Top-p 模型就更聪明”</strong>：采样参数只改变输出的选择方式，不会增加知识或推理能力。</li><li><strong>“回答流畅就说明内容正确”</strong>：流畅和正确是两回事，重要结论需要自行核对来源。</li><li><strong>“接入 RAG 或 Agent 就会自动可靠”</strong>：检索质量、权限控制和失败路径决定实际效果，接入不等于可靠。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-为什么这份知识库不要求所有人采用同一条阅读路线" tabindex="-1">1. 为什么这份知识库不要求所有人采用同一条阅读路线？ <a class="header-anchor" href="#_1-为什么这份知识库不要求所有人采用同一条阅读路线" aria-label="Permalink to &quot;1. 为什么这份知识库不要求所有人采用同一条阅读路线？&quot;">​</a></h3><details><summary>查看答案</summary><p>因为大模型原理、应用实践和 AI 绘画解决的问题不同，它们只共享一部分基础概念。按当前目标组合页面更容易形成完整认识，也能避免为了“完成顺序”阅读暂时用不到的内容。</p></details><h3 id="_2-如果目标是-ai-绘画-应从哪些页面进入-为什么仍建议了解-ai-基础" tabindex="-1">2. 如果目标是 AI 绘画，应从哪些页面进入？为什么仍建议了解 AI 基础？ <a class="header-anchor" href="#_2-如果目标是-ai-绘画-应从哪些页面进入-为什么仍建议了解-ai-基础" aria-label="Permalink to &quot;2. 如果目标是 AI 绘画，应从哪些页面进入？为什么仍建议了解 AI 基础？&quot;">​</a></h3><details><summary>查看答案</summary><p>可以从底模、模型组成、基本原理、模型生态和 LoRA 这组页面进入。绘画模型同样涉及模型、训练、推理和提示条件；先了解 AI 基础，会更容易理解这些共同概念，但不要求先学完大模型原理。</p></details><h3 id="_3-一周入门结束时-怎样判断自己是否有收获" tabindex="-1">3. 一周入门结束时，怎样判断自己是否有收获？ <a class="header-anchor" href="#_3-一周入门结束时-怎样判断自己是否有收获" aria-label="Permalink to &quot;3. 一周入门结束时，怎样判断自己是否有收获？&quot;">​</a></h3><details><summary>查看答案</summary><p>不看读了几页，而看能否用自己的话复述概念关系，并留下概念笔记、实验记录、改进过的 Prompt 和待查术语清单。能准确指出自己还不懂什么，也是一种有效产出。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>返回总览：</strong> <a href="/">首页</a>介绍本站定位与全部主题入口。</li><li><strong>共同基础：</strong> <a href="/ai/basics">AI 基础概念</a>适合不确定起点时先读。</li><li><strong>随时查词：</strong> <a href="/glossary">术语表</a>汇总各主题中的常见术语。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><p>以下资料适合在选定主题后继续深入，不必一次全部阅读：</p><ul><li><a href="https://developers.google.com/machine-learning/crash-course" target="_blank" rel="noreferrer">Google：Machine Learning Crash Course</a>：Google 官方机器学习速成课程，对应 AI 基础。</li><li><a href="https://www.3blue1brown.com/topics/neural-networks" target="_blank" rel="noreferrer">3Blue1Brown：Neural Networks</a>：可视化的神经网络系列视频，辅助建立基础直觉。</li><li><a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">Hugging Face LLM Course</a>：Hugging Face 官方大模型课程，对应大模型原理。</li><li><a href="https://huggingface.co/docs/diffusers/index" target="_blank" rel="noreferrer">Hugging Face：Diffusers 文档</a>：扩散模型官方文档，对应 AI 绘画主题。</li></ul>`,51)])])}const f=e(o,[["render",i]]);export{m as __pageData,f as default};
